def approve_existing_profiles(apps, schema_editor):
    UserProfile = apps.get_model("coordinator", "UserProfile")
    UserProfile.objects.filter(role="volunteer").update(is_approved=True)

    for profile in UserProfile.objects.filter(
        community__isnull=False,
    ).select_related("community").iterator():
        community = profile.community
        profile.province = community.province
        profile.district = community.district
        profile.sector = community.sector
        profile.cell = community.cell
        profile.village = community.village
        profile.save(update_fields=[
            "province",
            "district",
            "sector",
            "cell",
            "village",
        ])


